/* The pool of 25 hidden cases. A case is chosen from the specialties that sit at the table:
     must  - every one of these has to be at the table (otherwise the case is never drawn)
     fit   - the case belongs to the table if any of these is present
     icu   - a case the intensivist can carry alone
   Vitals and values are [start, worst, best]:
     start - how the patient looks when the team arrives
     worst - where an untreated patient ends up (arrest territory)
     best  - where the patient settles once every step is done
   needs are the steps that stabilise the patient. due is the time (seconds) after which an undone
   step starts to hurt. w is how much the step matters. A step is met by any one of `any`, by all of `all`,
   by `cover` (the antibiotics given must together cover those organisms), and `count` repeats.      */

const n = (id, label, owner, due, w, o) => Object.assign({ id, label, owner, due, w }, o || {});

